tool_and_message_events.command:
/bin/bash -lc 'set -eu
audit_dir=$(mktemp -d "$PWD/.contract-audit.XXXXXX")
trap '"'rm -r -- \""'$audit_dir"'"' EXIT
cp -R release/. \""'$audit_dir/"
cp vendor/hono-4.13.19.tgz "$audit_dir/"
cd "$audit_dir"
TMPDIR="$audit_dir" npm install ./hono-4.13.19.tgz --offline --ignore-scripts --no-audit --no-fund --cache "$audit_dir/.npm"
npm test
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import app from './app.mjs';

const version = JSON.parse(readFileSync('node_modules/hono/package.json','utf8')).version;
assert.equal(version, '4.13.19');
console.log('Hono', version, 'Node', process.version);

const scenarios = [
  { name: 'valid', path: '/desk/k8', session: true, status: 200, body: {id:'k8',title:'River'}, steps:'dispatch,session,read' },
  { name: 'no session', path: '/desk/k8', session: false, status: 401, body: {error:'sign_in'}, steps:'dispatch,session' },
  { name: 'missing', path: '/desk/absent', session: true, status: 404, body: {error:'not_found'}, steps:'dispatch,session,read' },
  { name: 'invalid record', path: '/desk/m3', session: true, status: 502, body: {error:'invalid_record'}, steps:'dispatch,session,read,error' },
];
for (const {name, path, session, status, body, steps} of scenarios) {
  const res = await app.request(path, {method:'GET', headers: session ? {'x-shift':'day'} : {}});
  const actual = { status: res.status, body: await res.json(), steps: res.headers.get('x-desk-steps') };
  const expected = {status, body, steps};
  try {
    assert.match(res.headers.get('content-type') ?? '', /"'^application'"\\/json(?:;|"'$)/i);
    assert.deepEqual(actual, expected);
    console.log('"'PASS', name, JSON.stringify(actual));
  } catch {
    console.log('FAIL', name, JSON.stringify({actual,expected}));
    process.exitCode = 1;
  }
}
NODE"

